SELECT p.*, pt.name as patient_name, u.real_name as doctor_name FROM prescription p LEFT JOIN patient pt ON p.patient_id = pt.id LEFT JOIN sys_user u ON p.doctor_id = u.id
AND (pt.name LIKE CONCAT('%', #{keyword}, '%') OR p.prescription_no LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
ORDER BY p.create_time DESC LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM prescription p LEFT JOIN patient pt ON p.patient_id = pt.id
AND (pt.name LIKE CONCAT('%', #{keyword}, '%') OR p.prescription_no LIKE CONCAT('%', #{keyword}, '%'))
AND p.status = #{status}
